"""Lay students out in seating rows, sorted by last name."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def _name_key(student: Student) -> Tuple[str, str]:
    return (student.last_name, student.first_name)

def _validate(roster: List[Student], seats: int) -> None:
    if not roster:
        raise ValueError("no students to seat")
    if seats < 1:
        raise ValueError(
            f"seats per row must be positive: {seats}"
        )

def _chunk(
    roster: List[Student], size: int
) -> List[List[Student]]:
    ordered = sorted(roster, key=_name_key)
    rows = []
    for start in range(0, len(ordered), size):
        rows.append(ordered[start : start + size])
    return rows

def _row_text(number: int, seated: List[Student]) -> str:
    names = " | ".join(item.display_name for item in seated)
    return f"Row {number}: {names}"

# ---
def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    roster = list(students)
    _validate(roster, seats_per_row)
    rows = _chunk(roster, seats_per_row)
    return [_row_text(*pair) for pair in enumerate(rows, 1)]

