import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

# ---
def make_student(last_name, first_name):
    return Student("0", last_name, first_name, "A")

class SeatingRowTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            make_student("Halloway", "Juno"),
            make_student("Thistle", "Bram"),
            make_student("Dunmere", "Piet"),
            make_student("Varrow", "Ines"),
            make_student("Quillon", "Sefa")
        ]

    def test_rows_are_filled_in_last_name_order(self):
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Juno",
            "Row 2: Quillon, Sefa | Thistle, Bram",
            "Row 3: Varrow, Ines"
        ]
        lines = seating_rows(self.roster, 2)
        self.assertEqual(lines, expected)

    def test_input_order_does_not_matter(self):
        reversed_roster = list(reversed(self.roster))
        self.assertEqual(
            seating_rows(reversed_roster, 2),
            seating_rows(self.roster, 2)
        )

    def test_ties_on_last_name_break_on_first_name(self):
        pair = [
            make_student("Dunmere", "Piet"),
            make_student("Dunmere", "Anna")
        ]
        expected = ["Row 1: Dunmere, Anna | Dunmere, Piet"]
        self.assertEqual(seating_rows(pair, 2), expected)

    def test_one_wide_row_holds_everyone(self):
        lines = seating_rows(self.roster, 10)
        self.assertEqual(len(lines), 1)
        self.assertEqual(lines[0].count(" | "), 4)

    def test_one_seat_per_row(self):
        lines = seating_rows(self.roster, 1)
        self.assertEqual(len(lines), 5)
        self.assertEqual(lines[-1], "Row 5: Varrow, Ines")

    def test_accepts_any_iterable(self):
        lines = seating_rows(iter(self.roster), 2)
        self.assertEqual(len(lines), 3)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
